uint64_t gcd(uint64_t a, uint64_t b) {
  int c = __builtin_ctzll(a | b);
  a >>= __builtin_ctzll(a);
  b >>= __builtin_ctzll(b);
  if (a < b) {
    swap(a, b);
  }
  while (b) {
    do {
      a -= b;
      a >>= __builtin_ctzll(a);
    } while (a >= b);
    swap(a, b);
  }
  return a << c;
}

struct MinUnideque {
  using T = uint64_t;
  constexpr static T default_value = {};
  using C = stack<pair<T, T>>;

  static T op(T a, T b) {
    return gcd(a, b);
  }

  T get() const {
    return op(get(h), get(t));
  }

  void push_front(T x) {
    h.emplace(x, gcd(x, get(h)));
  }

  void push_back(T x) {
    t.emplace(x, gcd(x, get(t)));
  }

  void pop_back() {
    if (!t.empty()) {
      return t.pop();
    }
    while (h.size() > 1) {
      push_back(h.top().first);
      h.pop();
    }
    h.pop();
  }

  void pop_front() {
    if (!h.empty()) {
      return h.pop();
    }
    while (t.size() > 1) {
      push_front(t.top().first);
      t.pop();
    }
    t.pop();
  }

  void clear() {
    while (h.size()) {
      h.pop();
    }
    while (t.size()) {
      t.pop();
    }
  }

private:
  C h, t;

  static T get(const C& a) {
    return a.empty()? default_value: a.top().second;
  }
} gcdq;

