void Fast_Ostream::Put_Int(long long val) {
  if (val < 0) {
    operator<<('-');
    Put_Unsigned(~val + 1);
  } else {
    Put_Unsigned(val);
  }
}
void Fast_Ostream::Put_Unsigned(unsigned long long val) {
  char* _Stack = (char*)malloc(21);
  unsigned S_top = 0;
  while (val) {
    _Stack[++S_top] = (val % 10) ^ 48;
    val /= 10;
  }
  if (!S_top) {
    operator<<('0');
  }
  while (S_top) {
    operator<<(_Stack[S_top--]);
  }
  free(_Stack);
}
