void solve() {
  LL(N, K);
  VEC(ll, L, N);
  VEC(ll, R, N);
  vi A(N);
  FOR(i, N) A[i] = R[i] - L[i] + 1;

  ll ANS = infty<ll>;
  ll sm = 0;
  ll one = 0;
  ll get = 0;

  FOR(i, N) {
    if (sm >= K) break;
    if (sm + A[i] >= K) {
      ll x = L[i] + (K - sm) - 1;
      x += 2 * get + 2;
      chmin(ANS, x);
    }
    ll u = K - (sm + A[i]);
    if (u > 0 && u <= one) {
      ll x = R[i];
      x += 2 * get + 2;
      x += 2 * u;
      chmin(ANS, x);
    }
    if (A[i] >= 2) {
      sm += A[i];
      get += 1;
    }
    if (A[i] == 1) { ++one; }
  }
  if (ANS == infty<ll>) ANS = -1;
  print(ANS);
}

