// --- Fast Input ---
struct FastReader {
    const int S = 1 << 20;
    char buf[1 << 20], *p = buf, *q = buf;

    inline int readchar() {
        if (p == q && (q = (p = buf) + fread(buf, 1, S, stdin)) == buf)
            return EOF;
        return *p++;
    }

    inline FastReader& operator>>(char &c) {
        c = readchar();
        return *this;
    }

    template<typename T>
    inline FastReader& operator>>(T &x) {
        x = 0; int f = 1; char c = readchar();
        while (c != EOF && (c < '0' || c > '9')) { 
            if (c == '-') f = -1; 
            c = readchar(); 
        }
        if (c == EOF) return *this; 
        while (c >= '0' && c <= '9') { 
            x = x * 10 + c - '0'; 
            c = readchar(); 
        }
        x *= f;
        return *this;
    }

    inline FastReader& operator>>(string &s) {
        s.clear();
        int c = readchar();
        while (c <= 32 && c != EOF) c = readchar();
        while (c > 32 && c != EOF) {
            s += c;
            c = readchar();
        }
        return *this;
    }
} fastin;

// --- Fast Output ---
struct FastWriter {
    const int S = 1 << 20;
    char buf[1 << 20], *p = buf;

    ~FastWriter() { fwrite(buf, 1, p - buf, stdout); }

    inline void putc(char c) {
        if (p == buf + S) { 
            fwrite(buf, 1, S, stdout); 
            p = buf; 
        }
        *p++ = c;
    }

    inline FastWriter& operator<<(char c) {
        putc(c);
        return *this;
    }

    template<typename T>
    inline FastWriter& operator<<(T x) {
        if (x < 0) { putc('-'); x = -x; }
        static char s[20];
        int top = 0;
        do { s[top++] = x % 10 + '0'; x /= 10; } while (x);
        while (top) putc(s[--top]);
        return *this;
    }

    inline FastWriter& operator<<(const char *s) {
        while (*s) putc(*s++);
        return *this;
    }

    // NEW: Added support for std::string
    inline FastWriter& operator<<(const string &s) {
        for (char c : s) putc(c);
        return *this;
    }
} fastout;

