using namespace std;

typedef long double LD;
const LD eps = 1e-8;
inline int sgn (LD x) { return fabs(x) < eps ? 0 : x > 0 ? 1 : -1; }
inline LD sqr (LD x) { return x * x; }

const int N = 35;

struct point
{
	LD x, y;
	point (LD xx = 0, LD yy = 0) { x = xx, y = yy; }
	LD len () { return sqrt(sqr(x) + sqr(y)); }
} P[N], s, t;
inline point operator+ (const point &a, const point &b) { return point(a.x + b.x, a.y + b.y); }
inline point operator- (const point &a, const point &b) { return point(a.x - b.x, a.y - b.y); }
inline LD operator* (const point &a, const point &b) { return a.x * b.y - b.x * a.y; } // DASH
inline LD operator^ (const point &a, const point &b) { return a.x * b.x + a.y * b.y; } // DOT
inline point operator* (LD l, const point &a) { return point(a.x * l, a.y * l); }
inline point operator/ (const point &a, LD l) { return (LD(1) / l) * a; }
inline istream& operator>> (istream &in, point &a) { return in >> a.x >> a.y; }
inline ostream& operator<< (ostream &out, point &a) { return out << a.x << ' ' << a.y << endl; }
inline bool operator== (const point &a, const point &b) { return sgn(a.x - b.x) == 0 && sgn(a.y - b.y) == 0; }

inline bool onSeg (point a, point s, point e) { return sgn((e - a).len() + (a - s).len() - (e - s).len()) == 0; }

inline pair<bool, point> getConj (point s1, point e1, point s2, point e2)
{
	LD a = (s2 - s1) * (e1 - s1), b = (e2 - s1) * (e1 - s1);
	if (sgn(a - b) == 0) return make_pair(false, point(0.0, 0.0));
	point r = (a * e2 - b * s2) / (a - b);
	if (!onSeg(r, s1, e1) || !onSeg(r, s2, e2)) return make_pair(false, r);
	return make_pair(true, r);
}

int n;

int solve ()
{
	cin >> s >> t >> n;
	for (int i = 1; i <= n; ++i) cin >> P[i];
	P[n + 1] = P[1];
	point ip[3]; int pos[3];
	int cnt = 0;
	for (int i = 1; i <= n; ++i)
	{
		auto it = getConj(s, t, P[i], P[i + 1]);
		if (it.first)
		{
			bool s(false);
			for (int j = 0; !s && j < cnt; ++j) if (ip[j] == it.second) s = true;
			if (s) continue;
			cerr << (pos[cnt] = i, ip[cnt++] = it.second) << endl;
		}
	}
	if (cnt < 2)
	{
		cout.setf(ios::fixed);
		cout << setprecision(10) << (t - s).len() << endl;
		return 0;
	}
	LD slen = 0, len1 = 0, len2 = 0;
	for (int i = 1; i <= n; ++i) slen += (P[i + 1] - P[i]).len();
	len1 += (ip[0] - P[pos[0] + 1]).len();
	for (int i = pos[0] + 1; i < pos[1]; ++i) len1 += (P[i + 1] - P[i]).len();
	len1 += (ip[1] - P[pos[1]]).len();
	len2 = slen - len1;
	cerr << len1 << ' ' << len2 << endl;
	if ((s - ip[0]).len() > (s - ip[1]).len()) swap(ip[0], ip[1]);
	LD res = min(len1, len2) + (s - ip[0]).len() + (t - ip[1]).len();
	res = min(res, (ip[0] - s).len() + (ip[1] - ip[0]).len() * 2.0 + (t - ip[1]).len());
	cout.setf(ios::fixed);
	cout << setprecision(10) << res << endl;
	return 0;
}

int main ()
{
#ifdef LOCAL
	freopen("in", "r", stdin);
#endif
	return solve();
}

