int Pow(int a, int b)
{
    int ans = 1;
    while (b)
    {
        if (b & 1)
            ans = (ans * a) % MOD;
        a = (a * a) % MOD;
        b >>= 1;
    }
    return ans;
}

int Modulo(int a, int b)
{
    return a * Pow(b, MOD - 2) % MOD;
}

void Solve()
{
    string s;
    int k;
    cin >> s >> k;
    int x = 0, y = 1;
    for (int i = 0; i < s.size(); i++)
    {
        if (s[i] == '0' || s[i] == '5')
            x = (x + y) % MOD;
        y = (y << 1) % MOD;
    }
    int d = Pow(y, k) - 1;
    if (d < 0)
        d += MOD;
    y = Modulo(d, y - 1 + (y == 0) * MOD);
    cout << (x * y) % MOD;
}

