	ll extra = 0;
	for(int i = 0; i < N; i++){
		cin >> C[i];
		tot += C[i];
		if(C[i] >= 2){
			ans += C[i];
			extra += (C[i] - 2) / 2;
		} else {
			singles++;
		}
	}
	ans += min(singles, extra);
	ll other = min(tot, C[N-1] + C[N-1] / 2);
