ll XOR(ll m, ll n)
{
    ll a[4];

    if(m%2)
    {
        a[0]=m, a[1]=m^n, a[2]=m-1, a[3]=(m-1)^n;
    }

    else
    {
        a[0]=n,a[1]=1,a[2]=n^1,a[3]=0;
    }

    return a[(n-m)%4];
}

